def generate_good_numbers(limit):
    good_numbers = set()
    # Iterate over g >= 2
    for g in range(2, int(limit**0.5) + 2):
        g_sq = g * g
        # Iterate over x' < y' such that gcd(x', y') = 1
        for x_prime in range(1, int((limit / g_sq)**0.5) + 2):
            for y_prime in range(x_prime + 1, int((limit / g_sq)**0.5) + 2):
                if x_prime**2 + y_prime**2 > limit / g_sq:
                    break
                if abs(math.gcd(x_prime, y_prime)) == 1:
                    m = g_sq * (x_prime**2 + y_prime**2)
                    if m <= limit:
                        good_numbers.add(m)

    return sorted(list(good_numbers))

